coupon.remainingUses - 1;
return {
coupon: {
...coupon,
remainingUses,
status:
remainingUses === 0
? "used"
: coupon.status,
updatedAt: now,
},
redemption: {
couponId: coupon.id,
redeemedBy,
redeemedAt: now,
},
};
}
