type RedemptionFailureReason =
| "NOT_RECIPIENT"
| "EXPIRED"
| "NO_REMAINING_USES"
| "INACTIVE";
type RedemptionResult =
| {
success: true;
coupon: Coupon;
}
| {
success: false;
reason:
RedemptionFailureReason;
};
function redeemCoupon(
coupon: Coupon,
userId: string,
now: Date
): RedemptionResult {
if (
coupon.recipientId !== userId
) {
return {
success: false,
reason: "NOT_RECIPIENT",
};
}
if (
coupon.expiresAt !== null &&
coupon.expiresAt <= now
) {
return {
success: false,
reason: "EXPIRED",
};
}
if (
coupon.remainingUses <= 0
) {
return {
success: false,
reason:
"NO_REMAINING_USES",
};
}
if (
coupon.status !== "active"
) {
return {
success: false,
reason: "INACTIVE",
};
}
const remainingUses =
coupon.remainingUses - 1;
return {
success: true,
coupon: {
...coupon,
remainingUses,
status:
remainingUses === 0
? "used"
: coupon.status,
},
};
}
